"""Reconstruct July 2023 sales from warehouse dispatches."""

import csv
import json
from decimal import Decimal
from pathlib import Path


DATA_DIR = Path(__file__).resolve().parent / "dataset"
DISPOSAL_TIME = "2023-07-18 03:17:00"
COLD_ZONES = {"frozen", "meat"}


def read_csv(filename: str) -> list[dict[str, str]]:
    with (DATA_DIR / filename).open(newline="") as file:
        return list(csv.DictReader(file))


def number(value: str) -> Decimal:
    return Decimal(value.replace(",", "."))


def answer() -> int:
    catalog = read_csv("product_catalog.csv")
    by_product_id = {row["product_id"]: row for row in catalog}
    by_ean = {row["ean_code"]: row for row in catalog}

    # The simultaneous meat and frozen temperature breach brackets the
    # 03:17 batch, which is the unmistakable disposal trace.
    temperatures = {
        (row["timestamp"], row["zone"].strip().lower()): number(row["temperature_c"])
        for row in read_csv("temperature_logs.csv")
    }
    for zone in COLD_ZONES:
        safe_limit = {number(row["max_safe_temp_c"])
                      for row in catalog if row["storage_category"].lower() == zone}
        assert len(safe_limit) == 1
        for time in ("2023-07-18 02:00:00", "2023-07-18 04:00:00"):
            assert temperatures[(time, zone)] > next(iter(safe_limit))

    revenue = Decimal(0)
    disposal_count = 0
    for dispatch in read_csv("warehouse_dispatches.csv"):
        key = dispatch["product_id"]
        product = by_product_id.get(key) or by_ean.get(key)
        if product is None:
            raise ValueError(f"Unknown dispatched product: {key}")
        value = int(dispatch["quantity"]) * number(product["unit_price"])
        is_disposal = (dispatch["timestamp"] == DISPOSAL_TIME
                       and product["storage_category"].lower() in COLD_ZONES)
        if is_disposal:
            disposal_count += 1
        else:
            revenue += value

    assert disposal_count == 8
    assert revenue == revenue.to_integral_value()
    return int(revenue)


if __name__ == "__main__":
    with (Path(__file__).resolve().parent / "answer.json").open("w") as file:
        json.dump(answer(), file, default=list)
